    // One-time demo snapshot from Pulse API.
    static let clustersJSON = #"[{"id": "260527032", "title": "Ken Paxton Defeats Cornyn in Texas GOP Senate Primary", "summary": "Texas Attorney General Ken Paxton, backed by former President Trump, defeated incumbent Senator John Cornyn in a high-profile and expensive Republican Senate primary runoff. Paxton's victory, despite scandals and fundraising disadvantages, signals Trump's continued influence over the GOP and sets up a contentious general election against Democrat James Talarico. The result has energized Democrats, who see a new opportunity to flip the Texas Senate seat in November.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 19, "sourceCount": 0, "articles": []}, {"id": "260529004", "title": "Blue Origin Rocket Explosion Disrupts NASA Moon Plans", "summary": "Blue Origin's New Glenn rocket exploded during a test on a Florida launchpad, dealing a significant setback to Jeff Bezos' space company and raising concerns about delays to NASA's Artemis Moon program. The incident, which occurred just days before a planned satellite launch for Amazon, has cast doubt on Blue Origin's reliability as a competitor to SpaceX and may have broader implications for US space ambitions.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 18, "sourceCount": 0, "articles": []}, {"id": "260529008", "title": "Russian Drone Strike Hits Romanian Apartment Building", "summary": "A Russian drone, launched as part of an attack on Ukraine, crashed into an apartment building in Gala\u021bi, Romania, injuring two people and causing a fire. The incident, which marks the first time civilians in Romania have been injured by spillover from the Ukraine conflict, has drawn sharp condemnation from NATO, the EU, and Romanian officials, who are considering invoking NATO\u2019s Article 4. The event has heightened concerns about the risks of the Ukraine war spilling into NATO territory and prompted calls for a coordinated response against Russia.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 13, "sourceCount": 0, "articles": []}, {"id": "260530013", "title": "US Shifts Defense Focus to Asia, Praises China Ties", "summary": "At the Shangri-La Dialogue in Singapore, US Defense Secretary Pete Hegseth emphasized the strengthening of US alliances in Asia and highlighted improved relations with China. He simultaneously criticized longstanding European defense partners, signaling a strategic pivot toward the Indo-Pacific region and a more stable, pragmatic approach to China. This marks a notable shift in US defense priorities and rhetoric under the Trump administration.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 13, "sourceCount": 0, "articles": []}, {"id": "260526012", "title": "Record-Breaking Heatwave Sweeps Western Europe", "summary": "Western Europe, particularly the UK and France, is experiencing an unprecedented spring heatwave, with record-breaking temperatures for May. The extreme heat has led to several deaths in France, water shortages, surging power prices, and increased demand for cooling products, highlighting the growing impact of climate change on the region. Authorities have issued warnings as the heatwave disrupts daily life and infrastructure.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 13, "sourceCount": 0, "articles": []}, {"id": "260529051", "title": "SpaceX Lowers IPO Valuation Ahead of Debut", "summary": "SpaceX is preparing for its highly anticipated initial public offering, now targeting a valuation of at least $1.8 trillion\u2014down from earlier expectations of over $2 trillion. The adjustment comes as the company consults with advisers and investors, while interest from funds and retail investors remains high. The IPO is expected to be one of the largest in history, with significant implications for both Elon Musk's wealth and the broader market.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 12, "sourceCount": 0, "articles": []}, {"id": "260526030", "title": "Micron Surges Past $1 Trillion Amid AI Chip Boom", "summary": "Micron Technology shares have soared, briefly surpassing a $1 trillion market capitalization, as surging demand for AI-related memory chips drives a global supply crunch. UBS and other analysts have dramatically raised their price targets, projecting even higher valuations as Micron benefits from tight chip supplies and long-term agreements. The rally reflects broader investor enthusiasm for memory chipmakers amid the AI boom.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 12, "sourceCount": 0, "articles": []}, {"id": "260527038", "title": "US-Iran Deal Negotiations Face Stalemate", "summary": "Negotiations between the US and Iran remain stalled, with President Trump repeatedly stating that the US is 'not satisfied' with the current terms and emphasizing that Iran is under significant economic pressure. Meanwhile, Iranian hardliners and lawmakers insist on maximalist demands, and disputes over issues like the unfreezing of Iranian funds and the authenticity of reported draft agreements add further complexity. The situation is compounded by internal and external pressures on both sides, making a quick resolution unlikely.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 10, "sourceCount": 0, "articles": []}, {"id": "260524014", "title": "US-Iran Deal Nears to Reopen Strait of Hormuz", "summary": "The United States and Iran appear close to finalizing an agreement to end hostilities and reopen the strategic Strait of Hormuz, a vital global oil transit route. US officials, including Secretary of State Marco Rubio and President Trump, have signaled significant progress, with both sides reportedly agreeing in principle to the reopening, though some details\u2014particularly regarding Iran's nuclear program\u2014remain under negotiation. The potential deal has drawn international attention, with imminent announcements anticipated.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 9, "sourceCount": 0, "articles": []}, {"id": "260528050", "title": "Snowflake Surges on Strong Earnings and Amazon Deal", "summary": "Snowflake shares soared after the company reported a blowout quarter, issued a strong annual outlook, and announced a $6 billion multiyear partnership with Amazon Web Services. The rally, fueled by growing enterprise demand for AI and cloud solutions, marked Snowflake's best trading day since 2020 and lifted sentiment across the software sector. Analysts widely backed the company's prospects, citing its pivotal role in the AI-driven software landscape.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 8, "sourceCount": 0, "articles": []}, {"id": "260529048", "title": "Oil Prices Plunge on US-Iran Ceasefire Hopes", "summary": "Global oil prices experienced their steepest monthly decline in years, driven by optimism over potential US-Iran peace talks and a possible ceasefire. Hopes for the reopening of the Strait of Hormuz and resumed oil flows have contributed to the sharp drop, offering relief to consumers and impacting related financial markets. The market is closely watching for further developments in negotiations between the US and Iran.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 8, "sourceCount": 0, "articles": []}, {"id": "260528028", "title": "EU Fines Temu \u20ac200m Over Unsafe Products", "summary": "The European Commission has fined Chinese e-commerce platform Temu \u20ac200 million for failing to prevent the sale of illegal and dangerous products, including unsafe baby toys and faulty chargers. The penalty follows a lengthy investigation that found a high risk of consumers encountering unsafe items on Temu's website, marking one of the first major actions under the EU's Digital Services Act.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 8, "sourceCount": 0, "articles": []}, {"id": "260527009", "title": "Spanish Socialist Party HQ Raided in Corruption Probe", "summary": "Spanish police have raided the headquarters of the ruling Socialist Party in Madrid as part of a widening investigation into alleged corruption and judicial interference. The probe has intensified the political crisis facing Prime Minister Pedro S\u00e1nchez and his government. The searches are focused on uncovering potential illegal payments and influence peddling within the party.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 7, "sourceCount": 0, "articles": []}, {"id": "260526007", "title": "Federal Courts Block Alabama GOP Congressional Map", "summary": "A panel of federal judges has blocked Alabama from using a Republican-drawn congressional map, ruling that it intentionally discriminated against Black voters and violated the Constitution. The court's decision prevents the map from being used in upcoming elections, and Alabama is expected to appeal, potentially sending the case to the Supreme Court. The ruling underscores ongoing legal battles over redistricting and voting rights in the state.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 6, "sourceCount": 0, "articles": []}, {"id": "260530016", "title": "Escalating Ebola Outbreak in Central Africa", "summary": "A severe Ebola outbreak is rapidly spreading in the Democratic Republic of Congo and Central Africa, with infection rates and fatalities rising at an alarming pace. Medical workers face significant challenges due to travel restrictions, cultural practices, and limited resources, while global health officials warn of the outbreak's unprecedented speed and potential for wider impact.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 6, "sourceCount": 0, "articles": []}, {"id": "260528045", "title": "DOJ Opens Criminal Probe Into E. Jean Carroll", "summary": "The U.S. Justice Department has reportedly launched a criminal investigation into whether E. Jean Carroll committed perjury during her civil lawsuits against former President Donald Trump. The probe centers on allegations that Carroll may have lied about receiving outside financial support for her legal battles against Trump. This development follows multiple reports citing sources familiar with the matter.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 5, "sourceCount": 0, "articles": []}, {"id": "260529019", "title": "US-Iran Near Preliminary Ceasefire and Nuclear Talks", "summary": "The United States and Iran are reportedly close to finalizing a preliminary agreement that would extend a ceasefire for 60 days and initiate negotiations on Iran\u2019s nuclear program. The deal, which still requires approval from President Trump, could also lead to the reopening of the Strait of Hormuz and potentially end a three-month conflict that has disrupted the global economy. Optimism is growing as both sides signal willingness to move toward a lasting resolution.", "location": {"lat": 51.5074, "lng": -0.1278, "label": "Global"}, "occurredAt": "2026-05-30T22:12:48Z", "createdAt": "2026-05-30T22:12:48Z", "imageUrl": null, "articleCount": 4, "sourceCount": 0, "articles": []}]"#
